use anyhow::{Context,Result,bail};use axum::{extract::{Path as AxPath,State},http::StatusCode,response::IntoResponse,routing::get,Json,Router};use fluxvm_intelligence::{netintel,shield::{DEFAULT_SHIELD_PIN_ROOT,DEFAULT_SHIELD_STATE_ROOT},tcpintel::{DEFAULT_TCP_PIN_ROOT,DEFAULT_TCP_STATE_ROOT}};use serde_json::json;use std::{env,net::SocketAddr,path::PathBuf};use tokio::net::TcpListener;use uuid::Uuid;
#[derive(Clone)]struct ApiState{sp:PathBuf,ss:PathBuf,tp:PathBuf,ts:PathBuf}
fn roots()->ApiState{ApiState{sp:env::var("FLUXVM_SHIELD_PIN_ROOT").map(PathBuf::from).unwrap_or_else(|_|DEFAULT_SHIELD_PIN_ROOT.into()),ss:env::var("FLUXVM_SHIELD_STATE_ROOT").map(PathBuf::from).unwrap_or_else(|_|DEFAULT_SHIELD_STATE_ROOT.into()),tp:env::var("FLUXVM_TCP_PIN_ROOT").map(PathBuf::from).unwrap_or_else(|_|DEFAULT_TCP_PIN_ROOT.into()),ts:env::var("FLUXVM_TCP_STATE_ROOT").map(PathBuf::from).unwrap_or_else(|_|DEFAULT_TCP_STATE_ROOT.into())}}
fn usage()->&'static str{"usage: fluxvm-netintel snapshot <uuid> [flow_limit] | metrics | serve [127.0.0.1:7792]"}
#[tokio::main]async fn main()->Result<()>{let a:Vec<String>=env::args().collect();let r=roots();match a.get(1).map(String::as_str){Some("snapshot")=>{let id:Uuid=a.get(2).context(usage())?.parse()?;let lim=a.get(3).and_then(|v|v.parse().ok()).unwrap_or(128);println!("{}",serde_json::to_string_pretty(&netintel::snapshot(id,&r.sp,&r.ss,&r.tp,&r.ts,lim))?);Ok(())},Some("metrics")=>{print!("{}",netintel::prometheus(&r.sp,&r.ss,&r.tp,&r.ts));Ok(())},Some("serve")=>{let addr:SocketAddr=a.get(2).map(String::as_str).unwrap_or("127.0.0.1:7792").parse()?;let app=Router::new().route("/healthz",get(||async{Json(json!({"ok":true}))})).route("/v1/netintel/vms/{id}",get(vm)).route("/metrics",get(metrics)).with_state(r);let l=TcpListener::bind(addr).await?;axum::serve(l,app).await?;Ok(())},_=>bail!(usage())}}
async fn vm(State(r):State<ApiState>,AxPath(id):AxPath<String>)->impl IntoResponse{match id.parse::<Uuid>(){Ok(id)=>(StatusCode::OK,Json(json!(netintel::snapshot(id,&r.sp,&r.ss,&r.tp,&r.ts,256)))).into_response(),Err(_)=>(StatusCode::BAD_REQUEST,"invalid UUID").into_response()}}
async fn metrics(State(r):State<ApiState>)->impl IntoResponse{netintel::prometheus(&r.sp,&r.ss,&r.tp,&r.ts)}
